from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('gdp.xlsx', data_only=False)
print(wb.sheetnames)
for name in wb.sheetnames:
    ws=wb[name]
    print(name, ws.max_row, ws.max_column)
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row,45), min_col=1, max_col=min(ws.max_column,15), values_only=False):
        vals=[]
        for c in row:
            if c.value is not None: vals.append(f'{c.coordinate}={c.value!r}')
        if vals: print(' | '.join(vals))
    print('---')
