from openpyxl import load_workbook
wb=load_workbook('gdp.xlsx', data_only=False)
for name, bounds in [('Task',(33,71,1,13)),('Data',(20,40,1,18))]:
 ws=wb[name]
 print('\n',name)
 for row in ws.iter_rows(min_row=bounds[0],max_row=bounds[1],min_col=bounds[2],max_col=bounds[3]):
  values=[f'{cell.coordinate}={cell.value!r}' for cell in row if cell.value is not None]
  if values: print(' | '.join(values))
print('\nTask expected cells styles:')
ws=wb['Task']
for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L48']:
 print(rng)
 for row in ws[rng]: print(' '.join(f'{c.coordinate}[style={c.style_id},fill={c.fill.fgColor.rgb or c.fill.fgColor.indexed},num={c.number_format}]' for c in row))
